package kr.danta.core.snapshot;
import kr.danta.core.diplomacy.DiplomaticStatus;import org.junit.jupiter.api.Test;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class Dev090DiplomacySnapshotTest {
 @Test void v16RoundTripPreservesDiplomacy(){GameSnapshot s=new GameSnapshot(GameSnapshot.CURRENT_SCHEMA,1,2,false,1.0,null,null,List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(new DiplomaticRelationSnapshot("blue","red",DiplomaticStatus.ALLIANCE)),List.of());GameSnapshot d=GameSnapshotCodec.decode(GameSnapshotCodec.encode(s));assertEquals(1,d.diplomaticRelations().size());assertEquals(DiplomaticStatus.ALLIANCE,d.diplomaticRelations().getFirst().status());}
 @Test void oldV15StillDecodesWithEmptyDiplomacy(){GameSnapshot s=new GameSnapshot(15,1,2,false,1.0,null,null,List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of());String encoded=GameSnapshotCodec.encode(s);String legacy=encoded.substring(0,encoded.lastIndexOf('|'));GameSnapshot d=GameSnapshotCodec.decode(legacy);assertTrue(d.diplomaticRelations().isEmpty());}
}
